import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n < 5:
        return 'C'
    if n >= 99:
        return 'D'
    own = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_recent = opp[-10:]
    opp_decay = 0.0
    w = 1.0
    totalw = 0.0
    for a in reversed(opp):
        if a == 'D':
            opp_decay += w
        totalw += w
        w *= 0.93
    d_rate_recent = sum(1 for a in opp_recent if a == 'D') / len(opp_recent)
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    if n >= 20:
        recent_c = sum(1 for a in opp[-20:] if a == 'C')
        if recent_c >= 19:
            return 'D'
    if n >= 10 and opp[-1] == 'D' and opp[-2] == 'D':
        if opp_d * 4 > n:
            return 'D'
    if n >= 6:
        last6 = opp[-6:]
        if last6.count('D') >= 4:
            return 'D'
    if n >= 3 and opp[-1] == opp[-2] == opp[-3] == 'D':
        return 'D'
    if n >= 12:
        last12 = opp[-12:]
        if last12[-3:] == ['C', 'C', 'C'] and last12.count('C') >= 10:
            if n % 7 == 0:
                return 'D'
            return 'C'
    if d_rate_recent > 0.4:
        if rng.random() < 0.35 + 0.4 * d_rate_recent:
            return 'D'
    if n >= 8:
        if opp[-1] == 'D' and opp[-2] == 'C' and opp[-3] == 'D':
            if rng.random() < 0.5:
                return 'D'
    if n >= 25 and opp_decay > 0:
        ratio = opp_decay / max(totalw, 1e-9)
        if ratio > 0.3 and rng.random() < 0.25:
            return 'D'
    if n % 9 == 8 and d_rate_recent < 0.15:
        return 'D'
    return 'C'

